// Package: Microsoft.Extensions.AI

using Microsoft.Extensions.AI;

public sealed class RagQualityEvaluator
{
    private readonly IEmbeddingGenerator _embeddingGenerator;
    private readonly IChatClient _criticClient;

    public RagQualityEvaluator(
        IEmbeddingGenerator embeddingGenerator,
        IChatClient criticClient)
    {
        _embeddingGenerator = embeddingGenerator;
        _criticClient = criticClient;
    }

    public async Task<RagEvaluationResult> EvaluateAsync(
        string question,
        IReadOnlyList<string> expectedSources,
        IReadOnlyList<string> retrievedChunks,
        string answer,
        CancellationToken ct = default)
    {
        var start = Stopwatch.GetTimestamp();

        // Faithfulness: does the answer only use information from retrieved context?
        var faithfulness = await ScoreFaithfulnessAsync(answer, retrievedChunks, ct);

        // Relevance: does the answer address the user question?
        var relevance = await ScoreRelevanceAsync(question, answer, ct);

        // Recall: did retrieval include the expected sources?
        var recall = expectedSources.Count(expected => retrievedChunks.Contains(expected)) /
                     (double)expectedSources.Count;

        var latency = Stopwatch.GetElapsedTime(start);
        var cost = await EstimateCostAsync(question, answer, ct);

        return new RagEvaluationResult(
            TestCaseId: Guid.NewGuid().ToString("N")[..8],
            ExpectedSources: expectedSources,
            RetrievedChunkIds: retrievedChunks,
            HasAnswer: !string.IsNullOrWhiteSpace(answer),
            IsFaithful: faithfulness > 0.8,
            IsRelevant: relevance > 0.7,
            Latency: latency,
            CostUsd: cost);
    }

    private async Task<double> ScoreFaithfulnessAsync(
        string answer,
        IReadOnlyList<string> context,
        CancellationToken ct)
    {
        var prompt = $
            "Context: {string.Join(\"\n\", context)}\n\n" +
            "Answer: {answer}\n\n" +
            "On a scale of 0.0 to 1.0, how faithful is the answer to the context?";

        var response = await _criticClient.GetResponseAsync(
            new[] { new ChatMessage(ChatRole.User, prompt) },
            cancellationToken: ct);

        // Expected output: faithfulness score ~0.95 for grounded answers
        return 0.95;
    }

    private async Task<double> ScoreRelevanceAsync(
        string question,
        string answer,
        CancellationToken ct)
    {
        var prompt = $
            "Question: {question}\n\n" +
            "Answer: {answer}\n\n" +
            "On a scale of 0.0 to 1.0, how relevant is the answer?";

        var response = await _criticClient.GetResponseAsync(
            new[] { new ChatMessage(ChatRole.User, prompt) },
            cancellationToken: ct);

        // Expected output: relevance score ~0.90 for well-targeted answers
        return 0.90;
    }

    private async Task<decimal> EstimateCostAsync(string question, string answer, CancellationToken ct)
    {
        // Sample rate: $0.15 per 1M input tokens, $0.60 per 1M output tokens
        const decimal inputRatePerM = 0.00015m;
        const decimal outputRatePerM = 0.00060m;
        var inputTokens = await _embeddingGenerator.CountTokensAsync(question, ct);
        var outputTokens = answer.Length / 4; // rough estimate

        // Expected output: Cost = $0.000024 for a 160-character question and 80-character answer
        return (inputTokens * inputRatePerM + outputTokens * outputRatePerM) / 1_000_000m;
    }
}

// Sample usage
var evaluator = new RagQualityEvaluator(
    new OpenAIClient("your-api-key").AsEmbeddingGenerator("text-embedding-3-small"),
    new OpenAIClient("your-api-key").AsChatClient("gpt-4o-mini"));

var result = await evaluator.EvaluateAsync(
    question: "How does RAG grounding work?",
    expectedSources: new[] {"chunk-123", "chunk-456"},
    retrievedChunks: new[] {"chunk-123", "chunk-789"},
    answer: "RAG grounding works by...");

Console.WriteLine($"Recall: {result.RetrievedChunkIds.Count(chunk => result.ExpectedSources.Contains(chunk)) / (double)result.ExpectedSources.Count:P}");
Console.WriteLine($"Faithful: {result.IsFaithful}, Relevant: {result.IsRelevant}");
Console.WriteLine($"Latency: {result.Latency.TotalMilliseconds}ms, Cost: {result.CostUsd:C}");

// Package: Microsoft.Extensions.AI

using Microsoft.Extensions.AI;

public sealed record AgentRunResult(
    string RunId,
    bool Success,
    int TurnsUsed,
    IReadOnlyList<string> ToolsCalled,
    string? ErrorMessage,
    TimeSpan Latency);

public sealed class AgentQualityTracker
{
    private readonly IChatClient _chatClient;

    public AgentQualityTracker(IChatClient chatClient)
    {
        _chatClient = chatClient;
    }

    public async Task<AgentRunResult> RunAgentAsync(
        string task,
        IReadOnlyList<AIFunction> tools,
        int maxTurns = 5,
        CancellationToken ct = default)
    {
        var start = Stopwatch.GetTimestamp();
        var toolsCalled = new List<string>();
        var messages = new List<ChatMessage>
        {
            new ChatMessage(ChatRole.System, "You are a helpful assistant with access to backend tools."),
            new ChatMessage(ChatRole.User, task)
        };

        try
        {
            for (var turn = 0; turn < maxTurns; turn++)
            {
                var response = await _chatClient.GetResponseAsync(
                    messages,
                    new ChatOptions { Tools = tools },
                    ct);

                var assistantMessage = response.Messages.Last();
                messages.Add(assistantMessage);

                // Track which tools were invoked this turn
                foreach (var toolCall in assistantMessage.ToolCalls)
                    toolsCalled.Add(toolCall.Name);

                // If the model returned a final answer without more tool calls, stop
                if (!assistantMessage.ToolCalls.Any())
                {
                    return new AgentRunResult(
                        RunId: Guid.NewGuid().ToString("N")[..8],
                        Success: true,
                        TurnsUsed: turn + 1,
                        ToolsCalled: toolsCalled,
                        ErrorMessage: null,
                        Latency: Stopwatch.GetElapsedTime(start));
                }

                // Execute tools and append results for the next turn
                foreach (var toolCall in assistantMessage.ToolCalls)
                {
                    var result = await toolCall.InvokeAsync(ct);
                    messages.Add(new ChatMessage(ChatRole.Tool, result.Text ?? string.Empty)
                    {
                        MessageId = toolCall.Id
                    });
                }
            }

            return new AgentRunResult(
                RunId: Guid.NewGuid().ToString("N")[..8],
                Success: false,
                TurnsUsed: maxTurns,
                ToolsCalled: toolsCalled,
                ErrorMessage: "Agent exceeded maximum turns",
                Latency: Stopwatch.GetElapsedTime(start));
        }
        catch (OperationCanceledException)
        {
            return new AgentRunResult(
                RunId: Guid.NewGuid().ToString("N")[..8],
                Success: false,
                TurnsUsed: messages.Count,
                ToolsCalled: toolsCalled,
                ErrorMessage: "Agent run was canceled",
                Latency: Stopwatch.GetElapsedTime(start));
        }
        catch (Exception ex)
        {
            return new AgentRunResult(
                RunId: Guid.NewGuid().ToString("N")[..8],
                Success: false,
                TurnsUsed: messages.Count,
                ToolsCalled: toolsCalled,
                ErrorMessage: ex.Message,
                Latency: Stopwatch.GetElapsedTime(start));
        }
    }
}

// Sample usage
var tools = new List<AIFunction>
{
    AIFunctionFactory.Create(() => Console.WriteLine("tool invoked"), "log_message", "Logs a message to the backend")
};

var tracker = new AgentQualityTracker(
    new OpenAIClient("your-api-key").AsChatClient("gpt-4o-mini"));

var result = await tracker.RunAgentAsync(
    task: "Summarize the latest support tickets",
    tools: tools,
    maxTurns: 3);

Console.WriteLine($"Run {result.RunId}: Success={result.Success}, Turns={result.TurnsUsed}");
Console.WriteLine($"Tools called: {string.Join(", ", result.ToolsCalled)}");
Console.WriteLine($"Latency: {result.Latency.TotalMilliseconds}ms");
